const updateCurrentNavLink = (targetId) => {
    document.querySelectorAll('nav a').forEach(link => {
        const href = link.getAttribute('href');
        if (href === `#${targetId}`) {
            link.setAttribute('aria-current', 'page');
        } else {
            link.removeAttribute('aria-current');
        }
    });
};

if ('IntersectionObserver' in window) {
    const sections = document.querySelectorAll('article[data-section]');
    const observer = new IntersectionObserver(entries => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                updateCurrentNavLink(entry.target.id);
                window.history.replaceState(null, '', `#${entry.target.id}`);
            }
        });
    }, { rootMargin: '-50% 0px -50% 0px' });
    sections.forEach(section => observer.observe(section));
} else {
    updateCurrentNavLink(window.location.hash.slice(1) || 'features');
    window.addEventListener('hashchange', () => {
        const targetId = window.location.hash.slice(1);
        if (targetId) updateCurrentNavLink(targetId);
    });
}

